75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /** Dedicated notification logger; a successful create enqueues a welcome notification here carrying the new owner's id and member id. */
84	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
85	
86	    /**
87	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
88	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
89	     * controller instance handled the request.
90	     */
91	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
92	
93	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
94	    private static final int MAX_OWNERS_PER_CITY = 50;
95	
96	    /** Once a city already holds at least this many owners (but is not yet full), a further create there is flagged with a capacity warning. */
97	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
98	
99	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
100	    private static final int MAX_OWNERS_PER_DAY = 100;
101	
102	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
103	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
104	
105	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
106	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
107	
108	    /**
109	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
110	     * create with an already-seen key returns the original owner instead of creating a duplicate.
111	     */
112	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
113	
114	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
115	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
116	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
117	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
118	
119	    private final ClinicService clinicService;
120	
121	    private final OwnerMapper ownerMapper;
122	
123	    private final PetMapper petMapper;
124	
125	    private final VisitMapper visitMapper;
126	
127	    private final TelephoneNormalizer telephoneNormalizer;
128	
129	    private final AddressNormalizer addressNormalizer;
130	
131	    private final EmailNormalizer emailNormalizer;
132	
133	    private final IdentityKeyResolver identityKeyResolver;
134	
135	    private final HouseholdResolver householdResolver;
136	
137	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
138	    private final HttpServletRequest request;
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper,
144	                                 TelephoneNormalizer telephoneNormalizer,
145	                                 AddressNormalizer addressNormalizer,
146	                                 EmailNormalizer emailNormalizer,
147	                                 IdentityKeyResolver identityKeyResolver,
148	                                 HouseholdResolver householdResolver,
149	                                 HttpServletRequest request) {
150	        this.clinicService = clinicService;
151	        this.ownerMapper = ownerMapper;
152	        this.petMapper = petMapper;
153	        this.visitMapper = visitMapper;
154	        this.telephoneNormalizer = telephoneNormalizer;
155	        this.addressNormalizer = addressNormalizer;
156	        this.emailNormalizer = emailNormalizer;
157	        this.identityKeyResolver = identityKeyResolver;
158	        this.householdResolver = householdResolver;
159	        this.request = request;
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
165	        Collection<Owner> owners;
166	        if (lastName != null) {
167	            owners = this.clinicService.findOwnerByLastName(lastName);
168	        } else {
169	            owners = this.clinicService.findAllOwners();
170	        }
171	        if (owners.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        owners.forEach(this::populateHouseholdMemberCount);
175	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
176	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        populateHouseholdMemberCount(owner);
187	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
188	    }
189	
190	    /**
191	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
192	     * it depends on more than the single owner: the {@code identityKey} (see
193	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
194	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
195	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
196	     * mapper's uncapped one on the returned DTO.
197	     *
198	     * @param owner the owner to map
199	     * @return the owner DTO carrying its identity key and household-capped membership level
200	     */
201	    private OwnerDto toOwnerDto(Owner owner) {
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
204	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
205	        return ownerDto;
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
212	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
213	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
214	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
215	            if (replay != null) {
216	                return replay;
217	            }
218	        }
219	        Owner owner = createOwner(ownerFieldsDto);
220	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
221	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
222	        }
223	        return createdOwnerResponse(owner);
224	    }
225	
226	    /**
227	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
228	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
229	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
230	     * normally.
231	     *
232	     * @param idempotencyKey the client-supplied idempotency key from the request header
233	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
234	     */
235	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
236	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
237	        if (existingId == null) {
238	            return null;
239	        }
240	        Owner owner = this.clinicService.findOwnerById(existingId);
241	        if (owner == null) {
242	            return null;
243	        }
244	        populateHouseholdMemberCount(owner);
245	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
246	    }
247	
248	    /**
249	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
250	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
251	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
252	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
253	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
254	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
255	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
256	     *
257	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
258	     * @return the newly created, persisted owner
259	     */
260	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
261	        normalizeAndValidate(ownerFieldsDto);
262	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
263	        populateDerivedFields(owner, ownerFieldsDto);
264	        requireUniqueIdentity(owner);
265	        flagPossibleDuplicate(owner, ownerFieldsDto);
266	        this.clinicService.saveOwner(owner);
267	        populateHouseholdMemberCount(owner);
268	        auditOwnerCreated(owner);
269	        enqueueWelcomeNotification(owner);
270	        return owner;
271	    }
272	
273	    /**
274	     * Enqueues a welcome notification for a newly created owner by emitting a single line to the dedicated
275	     * {@link #NOTIFY} logger, carrying the owner's id and its {@code memberId} so the notification can be addressed to
276	     * the new member.
277	     *
278	     * @param owner the newly created, persisted owner, with all its derived fields already in place
279	     */
280	    private void enqueueWelcomeNotification(Owner owner) {
281	        NOTIFY.info("welcome notification enqueued: id={} memberId={}", owner.getId(), owner.getMemberId());
282	    }
283	
284	    /**
285	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
286	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
287	     * canonical URL.
288	     *
289	     * @param owner the newly created, persisted owner
290	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
291	     */
292	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
293	        OwnerDto ownerDto = toOwnerDto(owner);
294	        HttpHeaders headers = new HttpHeaders();
295	        headers.setLocation(UriComponentsBuilder.newInstance()
296	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
297	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
298	    }
299	
300	    /**
301	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
302	     * its id, member id and registration date alongside the membership level (see
303	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
304	     *
305	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
306	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
307	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see
308	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
309	     *
310	     * @param owner the newly created, persisted owner, with all its derived fields already in place
311	     */
312	    private void auditOwnerCreated(Owner owner) {
313	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
314	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
315	            MembershipLevelResolver.deriveMembershipLevel(owner));
316	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
317	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
318	        AUDIT.info(event.toJson());
319	    }
320	
321	    /**
322	     * Returns the owner's primary identifier — the unified {@code memberId} the structured {@link OwnerCreatedEvent}
323	     * carries as the owner's identity.
324	     *
325	     * @param owner the newly created, persisted owner
326	     * @return the owner's member id
327	     */
328	    private String primaryIdentifier(Owner owner) {
329	        return owner.getMemberId();
330	    }
331	
332	    /**
333	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
334	     * already exist, in the order each field depends on. The {@code memberId} is derived from the owner's own
335	     * fields (see {@link IdentityKeyResolver#deriveMemberId}); the {@code namesakeCount} (see
336	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
337	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
338	     * this owner is saved, so none counts the new owner itself; and the shared
339	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
340	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
341	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
342	     *
343	     * @param owner          the newly mapped owner about to be saved
344	     * @param ownerFieldsDto the incoming owner payload
345	     */
346	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
347	        owner.setMemberId(deriveUniqueMemberId(owner));
348	        owner.setNamesakeCount(countNamesakes(owner));
349	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
350	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
351	        assignHouseholdId(owner);
352	    }
353	
354	    /**
355	     * Derives an owner's {@code memberId} and de-duplicates it against the owners that already exist. The base id
356	     * is the pure derivation (see {@link IdentityKeyResolver#deriveMemberId}); when it collides with an existing
357	     * owner's {@code memberId} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
358	     * makes the whole id unique. Evaluated before the new owner is saved, so the collision check reflects only owners
359	     * that predate this create; distinct owners therefore always receive distinct member ids.
360	     *
361	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
362	     * @return the de-duplicated member id, unique across all existing owners
363	     */
364	    private String deriveUniqueMemberId(Owner owner) {
365	        String base = identityKeyResolver.deriveMemberId(owner);
366	        Collection<Owner> existing = this.clinicService.findAllOwners();
367	        String candidate = base;
368	        int n = 2;
369	        while (isMemberIdInUse(candidate, existing)) {
370	            candidate = base + "-" + n;
371	            n++;
372	        }
373	        return candidate;
374	    }
375	
376	    private boolean isMemberIdInUse(String memberId, Collection<Owner> existing) {
377	        return existing.stream().anyMatch(other -> memberId.equals(other.getMemberId()));
378	    }
379	
380	    /**
381	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
382	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
383	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
384	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
385	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
386	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
387	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
388	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
389	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
390	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
391	     * assigned (see {@link #requireUniqueIdentity}).
392	     *
393	     * @param ownerFieldsDto the incoming owner payload, mutated in place
394	     * @throws MissingOwnerFieldsException if any required field is missing or blank
395	     */
396	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
397	        normalizeAddress(ownerFieldsDto);
398	        validateRequiredFields(ownerFieldsDto);
399	        validatePostcode(ownerFieldsDto);
400	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
401	        ownerFieldsDto.setTelephone(telephone);
402	        requireCityHasCapacity(ownerFieldsDto.getCity());
403	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
404	        ownerFieldsDto.setRegistrationDate(registrationDate);
405	        requireDailyLimitNotReached(registrationDate);
406	        normalizeEmail(ownerFieldsDto);
407	    }
408	
409	    /**
410	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
411	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
412	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
413	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
414	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
415	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
416	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
417	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
418	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
419	     *
420	     * @param ownerFieldsDto the incoming owner payload, mutated in place
421	     */
422	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
423	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
424	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
425	        if (!line1.isEmpty()) {
426	            ownerFieldsDto.setAddressLine1(line1);
427	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
428	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
429	        }
430	        else {
431	            ownerFieldsDto.setAddressLine1(null);
432	            ownerFieldsDto.setAddressLine2(null);
433	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
434	        }
435	    }
436	
437	    /**
438	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
439	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
440	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
441	     * place so the caller can map and save it directly.
442	     *
443	     * @param ownerFieldsDto the incoming owner payload, mutated in place
444	     */
445	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
446	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
447	    }
448	
449	    /**
450	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
451	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
452	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
453	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
454	     * date is rejected.
455	     *
456	     * @param ownerFieldsDto the incoming owner payload
457	     * @return the effective registration date rolled forward onto a business day
458	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
459	     */
460	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
461	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
462	        if (effective == null) {
463	            effective = LocalDate.now();
464	        }
465	        else if (effective.isAfter(LocalDate.now())) {
466	            throw new FutureRegistrationDateException(
467	                "the registration date must not be later than the current server date");
468	        }
469	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
470	            || PUBLIC_HOLIDAYS.contains(effective)) {
471	            effective = effective.plusDays(1);
472	        }
473	        return effective;
474	    }
475	
476	    /**
477	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
478	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
479	     * further owner may be created for that day.
480	     *
481	     * @param registrationDate the adjusted business-day registration date of the owner being created
482	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
483	     */
484	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
485	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
486	            throw new DailyOwnerLimitExceededException(
487	                "the maximum number of owners for today has already been reached");
488	        }
489	    }
490	
491	    /**
492	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
493	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
494	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
495	     * warning threshold) so both express the same per-day count in one place.
496	     *
497	     * @param registrationDate the adjusted business-day registration date to count owners for
498	     * @return the number of existing owners registered on that day
499	     */
500	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
501	        return this.clinicService.findAllOwners().stream()
502	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
503	            .count();
504	    }
505	
506	    /**
507	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
508	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
509	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
510	     * reflects only owners that predate it.
511	     *
512	     * @param registrationDate the adjusted business-day registration date of the owner being created
513	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
514	     */
515	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
516	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
517	    }
518	
519	    /**
520	     * Counts how many existing owners already share the given owner's first and last name, compared
521	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
522	     * create; it is zero when the owner's name is unique.
523	     *
524	     * @param owner the newly mapped owner about to be saved
525	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
526	     */
527	    private int countNamesakes(Owner owner) {
528	        String firstName = owner.getFirstName();
529	        String lastName = owner.getLastName();
530	        return (int) this.clinicService.findAllOwners().stream()
531	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
532	                && lastName.equalsIgnoreCase(existing.getLastName()))
533	            .count();
534	    }
535	
536	    /**
537	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
538	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
539	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
540	     *
541	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
542	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
543	     * flat {@code address}.
544	     *
545	     * @param ownerFieldsDto the owner payload to validate
546	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
547	     */
548	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
549	        List<String> missingFields = new ArrayList<>();
550	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
551	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
552	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
553	        requireText(missingFields, "city", ownerFieldsDto.getCity());
554	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
555	        if (!missingFields.isEmpty()) {
556	            throw new MissingOwnerFieldsException(missingFields);
557	        }
558	    }
559	
560	    private void requireText(List<String> missingFields, String fieldName, String value) {
561	        if (value == null || value.isBlank()) {
562	            missingFields.add(fieldName);
563	        }
564	    }
565	
566	    /**
567	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
568	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
569	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
570	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
571	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
572	     *
573	     * @param ownerFieldsDto the incoming owner payload
574	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
575	     */
576	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
577	        String postcode = ownerFieldsDto.getPostcode();
578	        if (postcode == null) {
579	            return;
580	        }
581	        Region region = Region.forCity(ownerFieldsDto.getCity());
582	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
583	            throw new InvalidPostcodeException(
584	                "postcode " + postcode + " is not valid for the city's region " + region.name());
585	        }
586	    }
587	
588	    /**
589	     * Rejects creating an owner whose whole derived {@code identityKey} (see
590	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
591	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
592	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
593	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
594	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
595	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
596	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
597	     * does not block the create.
598	     *
599	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
600	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
601	     */
602	    private void requireUniqueIdentity(Owner owner) {
603	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
604	        boolean inUse = this.clinicService.findAllOwners().stream()
605	            .filter(existing -> !existing.isDeleted())
606	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
607	        if (inUse) {
608	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
609	        }
610	    }
611	
612	    /**
613	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
614	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
615	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
616	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
617	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
618	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
619	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
620	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
621	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
622	     *
623	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
624	     * @param ownerFieldsDto the incoming owner payload
625	     */
626	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
627	        owner.setPossibleDuplicate(false);
628	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
629	            return;
630	        }
631	        String postcode = owner.getPostcode();
632	        if (postcode == null || postcode.isBlank()) {
633	            return;
634	        }
635	        for (Owner existing : this.clinicService.findAllOwners()) {
636	            if (isPossibleDuplicateOf(owner, existing)) {
637	                owner.setPossibleDuplicate(true);
638	                owner.setPossibleDuplicateOf(existing.getId());
639	                return;
640	            }
641	        }
642	    }
643	
644	    /**
645	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
646	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
647	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
648	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
649	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
650	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
651	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
652	     *
653	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
654	     * @param existing an already-persisted owner to test the new owner against
655	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
656	     */
657	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
658	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
659	            && owner.getPostcode().equals(existing.getPostcode())
660	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
661	    }
662	
663	    /**
664	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
665	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
666	     *
667	     * @param city the city of the owner being created
668	     * @throws OwnerCityFullException if the city already contains 50 or more owners
669	     */
670	    private void requireCityHasCapacity(String city) {
671	        if (countOwnersInCity(city) >= MAX_OWNERS_PER_CITY) {
672	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
673	        }
674	    }
675	
676	    /**
677	     * Counts how many existing owners already belong to the given {@code city}, compared case-insensitively. Invoked
678	     * before the new owner is saved, so the count reflects only owners that predate this create; it never counts the
679	     * new owner itself. Factored out of {@link #requireCityHasCapacity} so the per-city owner count is expressed in one
680	     * place, mirroring how {@link #countOwnersRegisteredOn} backs the per-day rules.
681	     *
682	     * @param city the city to count owners for
683	     * @return the number of existing owners in that city
684	     */
685	    private long countOwnersInCity(String city) {
686	        return this.clinicService.findAllOwners().stream()
687	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
688	            .count();
689	    }
690	
691	    /**
692	     * Determines whether creating an owner in the given city should carry a capacity warning. The warning is raised
693	     * when the city (compared case-insensitively) already holds between {@value #CAPACITY_WARNING_THRESHOLD} and
694	     * {@code MAX_OWNERS_PER_CITY - 1} owners, i.e. it is approaching but has not yet reached the hard per-city limit of
695	     * {@value #MAX_OWNERS_PER_CITY}. Evaluated before the new owner is saved, so the count reflects only owners that
696	     * predate this create; the hard rejection at the limit (see {@link #requireCityHasCapacity}) still runs.
697	     *
698	     * @param city the city of the owner being created
699	     * @return {@code true} when the city already holds 40 to 49 owners, {@code false} otherwise
700	     */
701	    private boolean computeCapacityWarning(String city) {
702	        long count = countOwnersInCity(city);
703	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
704	    }
705	
706	    /**
707	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
708	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
709	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
710	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
711	     * such owners never match one another as a household.
712	     *
713	     * @param owner the newly mapped owner about to be saved
714	     */
715	    private void assignHouseholdId(Owner owner) {
716	        String postcode = owner.getPostcode();
717	        if (postcode == null || postcode.isBlank()) {
718	            owner.setHouseholdId(null);
719	            return;
720	        }
721	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
722	    }
723	
724	    /**
725	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
726	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
727	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
728	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
729	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
730	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
731	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
732	     *
733	     * @param owner the owner whose capped membership level should be computed
734	     * @return the membership level, capped at one above the existing household maximum
735	     */
736	    private int cappedMembershipLevel(Owner owner) {
737	        populateHouseholdMemberCount(owner);
738	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
739	        Integer cap = householdMembershipLevelCap(owner);
740	        return cap == null ? level : Math.min(level, cap);
741	    }
742	
743	    /**
744	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
745	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
746	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
747	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
748	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
749	     * member has no cap.
750	     *
751	     * @param owner the owner whose household level cap should be computed
752	     * @return one above the existing household maximum level, or {@code null} when no cap applies
753	     */
754	    private Integer householdMembershipLevelCap(Owner owner) {
755	        String householdId = owner.getHouseholdId();
756	        Integer id = owner.getId();
757	        if (householdId == null || id == null) {
758	            return null;
759	        }
760	        Integer maxLevel = null;
761	        for (Owner member : this.clinicService.findAllOwners()) {
762	            Integer memberId = member.getId();
763	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
764	                int memberLevel = cappedMembershipLevel(member);
765	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
766	            }
767	        }
768	        return maxLevel == null ? null : maxLevel + 1;
769	    }
770	
771	    /**
772	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
773	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
774	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
775	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
776	     * already been saved it is itself among the members returned.
777	     *
778	     * @param owner the owner whose household members should be resolved
779	     * @return the members of the owner's household, never empty
780	     */
781	    private List<Owner> householdMembers(Owner owner) {
782	        String householdId = owner.getHouseholdId();
783	        if (householdId == null) {
784	            return List.of(owner);
785	        }
786	        return this.clinicService.findAllOwners().stream()
787	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
788	            .toList();
789	    }
790	
791	    /**
792	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
793	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
794	     * owner itself). An owner with no household is counted as a household of one.
795	     *
796	     * @param owner the owner whose household size should be resolved
797	     */
798	    private void populateHouseholdMemberCount(Owner owner) {
799	        owner.setHouseholdMemberCount(householdMembers(owner).size());
800	    }
801	
802	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
803	    @Override
804	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
805	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
806	        if (currentOwner == null) {
807	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
808	        }
809	        validatePostcode(ownerFieldsDto);
810	        currentOwner.setAddress(ownerFieldsDto.getAddress());
811	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
812	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
813	        currentOwner.setCity(ownerFieldsDto.getCity());
814	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
815	        currentOwner.setLastName(ownerFieldsDto.getLastName());
816	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
817	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
818	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
819	        this.clinicService.saveOwner(currentOwner);
820	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
821	    }
822	
823	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
824	    @Transactional
825	    @Override
826	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
827	        Owner owner = this.clinicService.findOwnerById(ownerId);
828	        if (owner == null) {
829	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
830	        }
831	        owner.setDeleted(true);
832	        this.clinicService.saveOwner(owner);
833	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
834	    }
835	
836	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
837	    @Override
838	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
839	        Owner owner = this.clinicService.findOwnerById(ownerId);
840	        if (owner == null) {
841	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
842	        }
843	        HttpHeaders headers = new HttpHeaders();
844	        Pet pet = petMapper.toPet(petFieldsDto);
845	        owner.setId(ownerId);
846	        pet.setOwner(owner);
847	        pet.getType().setName(null);
848	        this.clinicService.savePet(pet);
849	        PetDto petDto = petMapper.toPetDto(pet);
850	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
851	            .buildAndExpand(pet.getId()).toUri());
852	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
853	    }
854	
855	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
856	    @Override
857	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
858	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
859	        if (currentOwner != null) {
860	            Pet currentPet = this.clinicService.findPetById(petId);
861	            if (currentPet != null) {
862	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
863	                currentPet.setName(petFieldsDto.getName());
864	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
865	                this.clinicService.savePet(currentPet);
866	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
867	            }
868	        }
869	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
870	    }
871	
872	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
873	    @Override
874	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
875	        HttpHeaders headers = new HttpHeaders();
876	        Visit visit = visitMapper.toVisit(visitFieldsDto);
877	        Pet pet = new Pet();
878	        pet.setId(petId);
879	        visit.setPet(pet);
880	        this.clinicService.saveVisit(visit);
881	        VisitDto visitDto = visitMapper.toVisitDto(visit);
882	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
883	            .buildAndExpand(visit.getId()).toUri());
884	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
885	    }
886	
887	
888	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
889	    @Override
890	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
891	        Owner owner = this.clinicService.findOwnerById(ownerId);
892	        if (owner != null) {
893	            Pet pet = owner.getPet(petId);
894	            if (pet != null) {
895	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
896	            }
897	        }
898	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
899	    }
900	}
